'use strict';

// MODULES //

var slice = require( '@stdlib/array/base/slice' );
var assign = require( './assign.js' );


// MAIN //

/**
* Returns a new array with all elements within a specified range replaced according to a provided callback function.
*
* @param {Collection} x - input array
* @param {integer} start - starting index (inclusive)
* @param {integer} end - ending index (exclusive)
* @param {Function} fcn - callback function
* @param {*} [thisArg] - callback function execution context
* @returns {Collection} output array
*
* @example
* function fcn() {
*     return 5;
* }
*
* var x = [ 1, 2, 3, 4 ];
*
* var out = toFilledBy( x, 1, 3, fcn );
* // returns [ 1, 5, 5, 4 ]
*
* var bool = ( out === x );
* // returns false
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
*
* function fcn() {
*     return 5;
* }
*
* var x = new Int32Array( [ 1, 2, 3, 4 ] );
*
* var out = toFilledBy( x, 1, 3, fcn );
* // returns <Int32Array>[ 1, 5, 5, 4 ]
*
* var bool = ( out === x );
* // returns false
*/
function toFilledBy( x, start, end, fcn, thisArg ) {
	var out = slice( x, 0, x.length );
	return assign( x, start, end, fcn, out, 1, 0, thisArg );
}


// EXPORTS //

module.exports = toFilledBy;
